const{chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
(async()=>{const browser=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await browser.newPage({viewport:{width:1100,height:1200}});const results=[],errors=[];p.on('pageerror',e=>errors.push(String(e)));const out='docs/styles/style2/implementation/original-settings';fs.mkdirSync(out,{recursive:true});
for(const [skin,w,h,orientation]of [['style2',440,782,'portrait'],['style2',320,400,'portrait'],['style2',844,440,'auto'],['style1',440,782,'portrait']]){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin,layout:'original',scene:'media-voice',seats:8,action:1,bb:1,width:w,height:h,orientation}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});const button=await p.locator('.mx-menu').boundingBox(),label=await p.locator('.mx-menu-label').boundingBox();const aligned=skin==='style1'||Math.abs(button.x-label.x)<1&&label.y>=button.y&&label.y+label.height<=button.y+button.height+1&&button.width>=43.9&&button.height>=43.9;
await p.locator('#audit-stage').screenshot({path:`${out}/${skin}-${w}x${h}.png`});if(skin==='style2'){await p.mouse.click(label.x+label.width/2,label.y+label.height/2)}else await p.locator('.mx-menu').click();const menu=await p.locator('.mx-menu').getAttribute('aria-expanded')==='true';await p.locator('.mx-menu-item[data-menu-action=UITexas_Setting]').click();const settings=await p.locator('.mx-settings-overlay:not([hidden])').isVisible();results.push({skin,w,h,orientation,button,label,aligned,menu,settings});}
fs.writeFileSync(out+'/results.json',JSON.stringify({results,errors},null,2));console.log({results:results.map(({button,label,...r})=>r),errors});if(errors.length||results.some(r=>!r.aligned||!r.menu||!r.settings))process.exitCode=1;await browser.close()})();
